type Detail = {post:Post;replies:Reply[];disclaimer:string}
function api<T=any>(path:string, options:RequestInit={}, showActivity=true) {
 const request=async()=>{
 const method=(options.method||'GET').toUpperCase(), needsCsrf=!['GET','HEAD','OPTIONS'].includes(method)&&!path.startsWith('/auth/code/')
 const headers=new Headers(options.headers)
 if(options.body)headers.set('Content-Type','application/json')
 const send=()=>fetch(`${API}${path}`,{...options,headers,credentials:'include'})
 if(needsCsrf){
  const tokenResponse=await fetch(`${API}/auth/csrf`,{credentials:'include',cache:'no-store'})
  if(!tokenResponse.ok)throw new Error('Could not prepare a secure request. Refresh the page and try again.')
  headers.set('X-XSRF-TOKEN',(await tokenResponse.json()).token)
 }
 let response=await send(), data=await response.json().catch(()=>null)
 if(!response.ok&&needsCsrf&&response.status===400&&data?.message==='Refresh the page and try again.'){
  const tokenResponse=await fetch(`${API}/auth/csrf`,{credentials:'include',cache:'no-store'})
  if(tokenResponse.ok){headers.set('X-XSRF-TOKEN',(await tokenResponse.json()).token);response=await send();data=await response.json().catch(()=>null)}
 }
 if(response.ok&&response.status!==204&&!response.headers.get('content-type')?.toLowerCase().includes('json'))
  throw new Error('The API is not connected to this deployment yet. Please try again later.')
 if(!response.ok)throw new Error(data?.message||data?.title||`Request failed (${response.status})`)
 return data as T
 }
 return showActivity?trackApiRequest(request):request()
}
async function refreshCsrf(){
 const response=await trackApiRequest(()=>fetch(`${API}/auth/csrf`,{credentials:'include',cache:'no-store'}))
 if(!response.ok)throw new Error('Could not prepare a secure request. Refresh the page and try again.')
 await response.json()
}
const nice = (v:string) => v?.replace(/_/g,' ').replace(/\b\w/g,(c:string)=>c.toUpperCase())||''
const err=(e:unknown)=>e instanceof Error?e.message:'Something went wrong. Please try again.'
function pageFromPath(pathname:string){const parts=pathname.split('/').filter(Boolean);if(!parts.length)return 'Home';if(parts[0]==='search')return 'Search';if(parts[0]==='communities')return parts[1]?'Community':'Communities';if(parts[0]==='members'&&parts[1])return 'MemberProfile';if(parts[0]==='profile')return 'Profile';if(parts[0]==='moderation')return 'Moderation';if(parts[0]==='facilities'&&parts[1])return 'Facility';return 'Home'}
function routeIdFromPath(pathname:string){const parts=pathname.split('/').filter(Boolean);return parts.length>1?decodeURIComponent(parts[1]):''}

